return [{ json: { kanal_id: start.kanal_id, start: Object.assign({}, start, { zugang: { ok: !fehler, fehler } }), zugang_ok: !fehler, zugang_fehler: fehler, neuer_schluessel, gueltig_bis, berechtigungen } }];

// ---- Plattform-Modul YouTube (Stefan 18.10.2026, Vertrag Migration 48, 1.3) ----
