const PL = 'youtube', NAME = 'YouTube';
const ABGELAUFEN_BEI_TOKEN = false;  // der Zugriffsschlüssel ist gerade erneuert; 401 danach = Rechte fehlen, nicht abgelaufen
const TAG_M = { views: 'views', engagedViews: 'engaged_views', estimatedMinutesWatched: 'minutes_watched', averageViewDuration: 'average_view_duration',
  likes: 'likes', comments: 'comments', shares: 'shares', subscribersGained: 'subscribers_gained', subscribersLost: 'subscribers_lost' };
