  const grund = e && Array.isArray(e.errors) && e.errors[0] && typeof e.errors[0].reason === 'string' ? e.errors[0].reason : '';
  const roh = e ? String(e.message || e.status || '') : '';
  const text = 'YouTube meldet: ' + (roh ? kurz(roh, 180) : 'HTTP ' + status) + (grund ? ' (' + kurz(grund, 40) + ')' : '');
