  for (let i = 0; i < neu.length; i += 50) {
    const teil = neu.slice(i, i + 50);
    st.angefragt.push(...teil);
    st.offen.push({ art: 'videos', basis: 'data_api', pfad: 'videos', query: { part: 'snippet,statistics,contentDetails', id: teil.join(','), maxResults: 50 } });
